import{_ as a,o as t,c as l,a2 as n}from"./chunks/framework.CdvW4CUT.js";const c=JSON.parse('{"title":"Replay system","description":"","frontmatter":{},"headers":[],"relativePath":"gameplay/replay_system.md","filePath":"gameplay/replay_system.md","lastUpdated":1793354681000}'),o={name:"gameplay/replay_system.md"};function i(r,e,s,h,p,d){return t(),l("div",null,[...e[0]||(e[0]=[n('<h1 id="replay-system" tabindex="-1">Replay system <a class="header-anchor" href="#replay-system" aria-label="Permalink to &quot;Replay system&quot;">​</a></h1><h2 id="explanation" tabindex="-1">Explanation <a class="header-anchor" href="#explanation" aria-label="Permalink to &quot;Explanation&quot;">​</a></h2><p>Ranked has a built-in replay system where you can watch your matches back to review what both you and your opponent did during the run. You can access your match replays by going to: Profile &gt; Matches &gt; Click on the match you want to watch &gt; Watch Replay.</p><h2 id="interface" tabindex="-1">Interface <a class="header-anchor" href="#interface" aria-label="Permalink to &quot;Interface&quot;">​</a></h2><p>Pressing the Escape key will bring up a bar which shows the progression of the run:</p><ul><li>Light blue – player is in the Overworld</li><li>Red – player is in the Nether</li><li>Purple – player is in the End</li></ul><p>Clicking along this bar allows you to skip to different parts of the run.</p><p>You can find the Replay Tutorial and the Replay Controls in the Game Menu.</p><h2 id="downloading-replays" tabindex="-1">Downloading Replays <a class="header-anchor" href="#downloading-replays" aria-label="Permalink to &quot;Downloading Replays&quot;">​</a></h2><ul><li>Replays are deleted after 7 days unless they are downloaded.</li><li>You can download a Replay by going to: Profile &gt; Matches &gt; Click on the match &gt; Download Replay, where you will then be asked to name it.</li><li>These Replays can then be found in the main Ranked menu by clicking on My Replays and will not be deleted.</li><li>The Replays of the top 50 fastest runs of each season will not be deleted.</li><li>You can only watch or download 5 Replays every minute.</li></ul>',10)])])}const u=a(o,[["render",i]]);export{c as __pageData,u as default};
